/// Blocks whose 1.8 material is `Material.FOILAGE` (the leaves).
pub const FOLIAGE: &[&str] = &[
    "minecraft:acacia_leaves",
    "minecraft:birch_leaves",
    "minecraft:dark_oak_leaves",
    "minecraft:jungle_leaves",
    "minecraft:oak_leaves",
    "minecraft:spruce_leaves",
];

/// `Material.blocksMovement` for a flattened block name.
pub fn blocks_movement(block: &str) -> bool {
    NON_BLOCKING.binary_search(&block).is_err()
}

/// `block.getMaterial() == Material.FOILAGE`.
pub fn is_foliage(block: &str) -> bool {
    FOLIAGE.binary_search(&block).is_ok()
}
